        return $this->videoLink;
    }

    /**
    * Sets videoLink.
    *
    * @param string|null $videoLink  <p><= 2,000 characters</p> <p>Hosted link to the product video.</p> <p>File types for linked videos must be .mp4, .mov or .m4v.</p> <p>File size cannot exceed 2GB.</p>
    *
    * @return $this
    */
    public function setVideoLink(?string $videoLink = null): self
    {
        $this->videoLink = $videoLink;

        return $this;
    }



}


